package tlsx_test

import (
	"crypto/tls"
	"errors"
	"testing"

	"github.com/egdaemon/eg/internal/tlsx"
	"github.com/stretchr/testify/require"
)

// DO NOT EDIT: This file was auto generated by egautotest.

func TestMustClone(t *testing.T) {
	t.Run("clones the config without options", func(t *testing.T) {
		orig := &tls.Config{MinVersion: tls.VersionTLS13}
		updated := tlsx.MustClone(orig)
		require.NotSame(t, orig, updated)
		require.True(t, updated.MinVersion == tls.VersionTLS13)
	})

	t.Run("applies a single option", func(t *testing.T) {
		orig := &tls.Config{}
		updated := tlsx.MustClone(orig, tlsx.OptionInsecureSkipVerify)
		require.True(t, updated.InsecureSkipVerify)
	})

	t.Run("applies multiple options", func(t *testing.T) {
		orig := &tls.Config{}
		updated := tlsx.MustClone(orig, tlsx.OptionNoClientCert, tlsx.OptionNextProtocols("h2", "http/1.1"))
		require.Equal(t, tls.NoClientCert, updated.ClientAuth)
		require.Equal(t, []string{"h2", "http/1.1"}, updated.NextProtos)
	})

	t.Run("does not mutate the original", func(t *testing.T) {
		orig := &tls.Config{}
		_ = tlsx.MustClone(orig, tlsx.OptionInsecureSkipVerify)
		require.False(t, orig.InsecureSkipVerify)
	})

	t.Run("panics when an option returns an error", func(t *testing.T) {
		orig := &tls.Config{}
		require.Panics(t, func() {
			tlsx.MustClone(orig, func(*tls.Config) error {
				return errors.New("boom")
			})
		})
	})
}
